CREATE DATABASE IF NOT EXISTS gmu_erp;
USE gmu_erp;

CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id BIGINT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE departments (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE courses (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, duration_years INT NOT NULL, department_id BIGINT NOT NULL, FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE students (id BIGINT PRIMARY KEY AUTO_INCREMENT, usn VARCHAR(30) NOT NULL UNIQUE, user_id BIGINT UNIQUE, department_id BIGINT NOT NULL, course_id BIGINT NOT NULL, semester INT NOT NULL, admission_date DATE NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (department_id) REFERENCES departments(id), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE faculty (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_code VARCHAR(30) NOT NULL UNIQUE, user_id BIGINT NOT NULL UNIQUE, department_id BIGINT NOT NULL, designation VARCHAR(100), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE subjects (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, credits INT NOT NULL, semester INT NOT NULL, course_id BIGINT NOT NULL, FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE enrollments (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, subject_id BIGINT NOT NULL, academic_year VARCHAR(9) NOT NULL, UNIQUE (student_id, subject_id, academic_year), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (subject_id) REFERENCES subjects(id));
CREATE TABLE attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, enrollment_id BIGINT NOT NULL, class_date DATE NOT NULL, status ENUM('PRESENT','ABSENT') NOT NULL, marked_by BIGINT NOT NULL, UNIQUE (enrollment_id, class_date), FOREIGN KEY (enrollment_id) REFERENCES enrollments(id), FOREIGN KEY (marked_by) REFERENCES faculty(id));
CREATE TABLE exams (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, academic_year VARCHAR(9) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL);
CREATE TABLE marks (id BIGINT PRIMARY KEY AUTO_INCREMENT, exam_id BIGINT NOT NULL, enrollment_id BIGINT NOT NULL, maximum_marks DECIMAL(5,2) NOT NULL, marks_obtained DECIMAL(5,2) NOT NULL, grade VARCHAR(3), UNIQUE (exam_id, enrollment_id), FOREIGN KEY (exam_id) REFERENCES exams(id), FOREIGN KEY (enrollment_id) REFERENCES enrollments(id));
CREATE TABLE fee_invoices (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, academic_year VARCHAR(9) NOT NULL, description VARCHAR(200) NOT NULL, amount DECIMAL(12,2) NOT NULL, due_date DATE NOT NULL, status ENUM('PENDING','PARTIAL','PAID','OVERDUE') NOT NULL DEFAULT 'PENDING', FOREIGN KEY (student_id) REFERENCES students(id));
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, paid_at DATETIME NOT NULL, reference_no VARCHAR(80) NOT NULL UNIQUE, method VARCHAR(30) NOT NULL, FOREIGN KEY (invoice_id) REFERENCES fee_invoices(id));
CREATE TABLE class_schedules (id BIGINT PRIMARY KEY AUTO_INCREMENT, subject_id BIGINT NOT NULL, faculty_id BIGINT NOT NULL, semester INT NOT NULL, room VARCHAR(60) NOT NULL, weekday VARCHAR(12) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, FOREIGN KEY (subject_id) REFERENCES subjects(id), FOREIGN KEY (faculty_id) REFERENCES faculty(id));

INSERT IGNORE INTO roles(name) VALUES ('ADMIN'), ('FACULTY'), ('STUDENT');
